#!/usr/bin/env bash
set -Eeuo pipefail

if [[ ${EUID:-$(id -u)} -ne 0 ]]; then
  echo 'Запустите установщик от root.' >&2
  exit 1
fi

WHEEL='/tmp/auto_photo_ingest-0.5.0-py3-none-any.whl'
EXPECTED_SHA='94aa026d35d5d7cf205fefc579069cae27305b36f91dd1eb0e41403749d37da8'

echo '[1/4] Останавливаю таймер на время обновления'
systemctl stop auto-photo-ingest.timer 2>/dev/null || true
systemctl stop auto-photo-ingest.service 2>/dev/null || true

echo '[2/4] Устанавливаю модуль 0.5.0'
base64 -d > "$WHEEL" <<'WHEEL_BASE64'

WHEEL_BASE64
echo "$EXPECTED_SHA  $WHEEL" | sha256sum -c -
/opt/auto-photo-ingest/venv/bin/pip install --no-deps --force-reinstall "$WHEEL"
chmod -R a+rX /opt/auto-photo-ingest/venv

echo '[3/4] Готовлю безопасную конфигурацию Alibaba Cloud'
install -d -m 0700 /etc/auto-photo-ingest
install -d -m 0755 /etc/systemd/system/auto-photo-ingest.service.d
cat > /etc/systemd/system/auto-photo-ingest.service.d/qwen.conf <<'EOF'
[Service]
EnvironmentFile=-/etc/auto-photo-ingest/qwen-cloud.env
Environment=VISION_PROVIDER=disabled
Environment=DASHSCOPE_URL=https://dashscope-intl.aliyuncs.com/compatible-mode/v1/chat/completions
Environment=DASHSCOPE_MODEL=qwen3-vl-plus
EOF

echo '[4/4] Устанавливаю мастер ввода API-ключа'
cat > /usr/local/sbin/auto-photo-qwen-cloud-setup <<'SETUP'
#!/usr/bin/env bash
set -Eeuo pipefail
if [[ ${EUID:-$(id -u)} -ne 0 ]]; then
  echo 'Запустите от root.' >&2
  exit 1
fi
read -rsp 'Вставьте Singapore DASHSCOPE API key (ввод скрыт): ' API_KEY
echo
if [[ ! "$API_KEY" =~ ^sk-[A-Za-z0-9_-]{16,200}$ ]]; then
  echo 'Формат ключа неверный.' >&2
  exit 1
fi
umask 077
ENV_TMP=$(mktemp /etc/auto-photo-ingest/qwen-cloud.env.XXXXXX)
printf 'DASHSCOPE_API_KEY=%s\nDASHSCOPE_URL=https://dashscope-intl.aliyuncs.com/compatible-mode/v1/chat/completions\nDASHSCOPE_MODEL=qwen3-vl-plus\n' "$API_KEY" > "$ENV_TMP"
chown root:root "$ENV_TMP"
chmod 600 "$ENV_TMP"
mv "$ENV_TMP" /etc/auto-photo-ingest/qwen-cloud.env

/opt/auto-photo-ingest/venv/bin/python - <<'PY'
import sqlite3
db = sqlite3.connect('/var/lib/auto-photo-ingest/catalogue.sqlite3')
db.execute('UPDATE model_attempts SET next_at=0')
db.commit()
db.close()
PY

echo 'Проверяю qwen3-vl-plus на трёх автомобилях...'
RESULT=$(runuser -u auto-photo-ingest -- env \
  VISION_PROVIDER=dashscope \
  DASHSCOPE_API_KEY="$API_KEY" \
  DASHSCOPE_URL=https://dashscope-intl.aliyuncs.com/compatible-mode/v1/chat/completions \
  DASHSCOPE_MODEL=qwen3-vl-plus \
  /opt/auto-photo-ingest/venv/bin/auto-photo-ingest screen-model \
  --provider dashscope --data-dir /var/lib/auto-photo-ingest --limit 3)
unset API_KEY
echo "$RESULT"

if grep -q '"succeeded": 3' <<<"$RESULT"; then
  sed -i 's/Environment=VISION_PROVIDER=disabled/Environment=VISION_PROVIDER=dashscope/' /etc/systemd/system/auto-photo-ingest.service.d/qwen.conf
  systemctl daemon-reload
  systemctl enable --now auto-photo-ingest.timer
  echo 'QWEN_CLOUD_READY: облачная модель работает, таймер включён.'
else
  echo 'QWEN_CLOUD_TEST_FAILED: таймер оставлен выключенным.' >&2
  exit 2
fi
SETUP
chmod 700 /usr/local/sbin/auto-photo-qwen-cloud-setup
systemctl daemon-reload

echo
echo 'QWEN_CLOUD_CODE_READY'
echo 'Теперь создайте Singapore API key и выполните: sudo auto-photo-qwen-cloud-setup'
